  constexpr bool rule_state_layout_matches_indices() {
    for (std::size_t position = 0; position < rule_state_fields.size(); ++position) {
      if (index(rule_state_fields[position].word) != position) {
        return false;
      }
    }
    return true;
  }

  static_assert(rule_state_word_count % 4u == 0u);
  static_assert(rule_state_vector_count == 16u);
  static_assert(rule_state_layout_matches_indices());
  static_assert(analysis_grid_names.size() == analysis_grid_channel_count);
  static_assert(layout_history_names.size() == layout_history_channel_count);
  static_assert(depth_history_names.size() == depth_history_channel_count);
  static_assert(meta_names.size() == meta_word_count);
  static_assert(dense_out_names.size() == dense_out_channel_count);
  static_assert(global_out_names.size() == global_out_word_count);
